<?php namespace App\Filament\Resources\PageResource\Pages; use App\Filament\Resources\PageResource; use App\Models\Page; use App\Services\EditorialTrash; use Filament\Actions\{Action,CreateAction}; use Filament\Resources\Pages\ListRecords; use Filament\Schemas\Components\Tabs\Tab; use Illuminate\Database\Eloquent\Builder; class ListPages extends ListRecords {protected static string $resource=PageResource::class; protected function getHeaderActions():array{return [CreateAction::make()->visible(fn (): bool => $this->activeTab !== 'trash'),Action::make('empty_trash')->label('Vider la Corbeille')->icon('heroicon-o-trash')->color('danger')->requiresConfirmation()->modalHeading('Vider la Corbeille ?')->modalDescription('Toutes les pages seront supprimées définitivement. Le comportement SEO des anciennes URL sera conservé.')->visible(fn (): bool => $this->activeTab === 'trash' && Page::onlyTrashed()->exists())->action(fn () => app(EditorialTrash::class)->emptyTrash(Page::class))];} public function getTabs():array{return ['active'=>Tab::make('Pages')->badge(Page::query()->count()),'trash'=>Tab::make('Corbeille')->badge(Page::onlyTrashed()->count())->modifyQueryUsing(fn (Builder $query): Builder => $query->onlyTrashed())];}}
